{
  "findings": [
    {
      "check_id": "CKV_K8S_23",
      "title": "Service account token exposure",
      "resource": "kubernetes_service_account_v1.pass",
      "severity": "HIGH",
      "explanation": "The service account is configured to mount a secret token by default, which can lead to token exposure if the pod using this service account is compromised. Explicitly disabling the automount of service account tokens reduces this risk."
    }
  ],
  "patched_code": "resource \"kubernetes_service_account_v1\" \"pass\" {\n  metadata {\n    name = \"terraform-example\"\n    namespace = \"brian\"\n  }\n  automount_service_account_token = false\n  secret {\n    name = \"${kubernetes_secret_v1.example.metadata.0.name}\"\n  }\n}\n",
  "fix_summary": "Added 'automount_service_account_token = false' to the service account to prevent automatic mounting of service account tokens, reducing the risk of token exposure."
}
